create or replace function get_schedule_planning_relations_v1() returns table(id uuid,relation_type text,mode text,weight numeric,left_selector jsonb,right_selector jsonb,parameters jsonb) language sql stable security definer set search_path=public as $$select r.id,r.relation_type,r.mode,r.weight,r.left_selector,r.right_selector,r.parameters from schedule_planning_relations r where r.active and r.mode<>'OFF' and tenant_row_allowed(r.institution_code) and (r.effective_from is null or r.effective_from<=current_date) and (r.effective_to is null or r.effective_to>=current_date) order by case r.mode when 'HARD' then 0 when 'MEDIUM' then 1 else 2 end,r.relation_type,r.id$$;